async function measureMainAlignment(page) {
	return page.evaluate(() => {
		const rect = element => {
			const box = element.getBoundingClientRect();
			return { left: box.left, right: box.right, top: box.top, bottom: box.bottom,
				documentTop: box.top + window.scrollY, width: box.width, height: box.height };
		};
		const contentRight = element => {
			const style = getComputedStyle(element), box = element.getBoundingClientRect();
			return box.right - parseFloat(style.borderRightWidth) - parseFloat(style.paddingRight);
		};
		const queryCard = document.getElementById('query-form');
		const resultCard = document.getElementById('query-results');
		const editorOptions = document.getElementById('query-options-toggle');
		const resultToolbar = resultCard.querySelector('.query-result-toolbar');
		const toolbarRect = resultToolbar.getBoundingClientRect();
		const visible = element => {
			const box = element.getBoundingClientRect();
			return box.width > 0 && box.height > 0 && !element.closest('[hidden], [inert]');
		};
		const actions = Array.from(resultCard.querySelectorAll(
			'.query-results__fullscreen, .query-result-download-toggle, .query-result-options-toggle'))
			.filter(visible).map(element => ({
				role: element.matches('.query-results__fullscreen') ? 'fullscreen'
					: element.matches('.query-result-download-toggle') ? 'download' : 'options',
				label: element.getAttribute('aria-label') || element.textContent.trim(), ...rect(element),
				toolbarTop: element.getBoundingClientRect().top - toolbarRect.top,
				toolbarLeft: element.getBoundingClientRect().left - toolbarRect.left
			})).sort((left, right) => left.left - right.left);
		const rows = [];
		for (const action of actions.slice().sort((left, right) => left.top - right.top || left.left - right.left)) {
			let row = rows.find(candidate => Math.abs(candidate.top - action.top) <= 0.75);
			if (!row) {
				row = { top: action.top, bottom: action.bottom, right: action.right, actions: [], items: [] };
				rows.push(row);
			}
			row.bottom = Math.max(row.bottom, action.bottom);
			row.right = Math.max(row.right, action.right);
			row.actions.push(action.role);
			row.items.push(action);
		}
		const resultMount = resultCard.querySelector('.query-result-embedded');
		const headers = Array.from(resultCard.querySelectorAll('h2')).map(element => ({
			text: element.textContent.trim(), visible: visible(element), ...rect(element)
		}));
		return {
			viewportWidth: document.documentElement.clientWidth,
			documentScrollWidth: document.documentElement.scrollWidth,
			expectedActionGap: parseFloat(getComputedStyle(document.body).getPropertyValue('--workbench-control-gap')),
			queryCard: rect(queryCard), resultCard: rect(resultCard),
			queryCardContentRight: contentRight(queryCard), resultCardContentRight: contentRight(resultCard),
			rendererPaddingRight: parseFloat(getComputedStyle(resultMount).paddingRight),
			editorOptions: rect(editorOptions), editorOptionsVisible: visible(editorOptions),
			resultToolbar: rect(resultToolbar), resultToolbarColumnGap: getComputedStyle(resultToolbar).columnGap,
			actions, rows, headers
		};
	});
}

function assertMainAlignment(geometry, viewportWidth, { requireNaturalFit = true } = {}) {
	expect.soft(geometry.actions, `${viewportWidth}px: all result actions are visible`).toHaveLength(3);
	expect.soft(geometry.documentScrollWidth, `${viewportWidth}px: the page has no horizontal overflow`)
		.toBeLessThanOrEqual(geometry.viewportWidth);
	expect.soft(Math.abs((geometry.queryCard.right - geometry.queryCardContentRight)
		- (geometry.resultCard.right - geometry.resultCardContentRight)),
	`${viewportWidth}px: editor and result cards share one inset`).toBeLessThanOrEqual(0.5);
	expect.soft(Math.abs(geometry.queryCardContentRight - geometry.resultCardContentRight),
	`${viewportWidth}px: editor and result content edges align`).toBeLessThanOrEqual(0.5);
	expect.soft(Math.abs(geometry.editorOptions.right - geometry.queryCardContentRight),
	`${viewportWidth}px: editor Options ends at its content edge`).toBeLessThanOrEqual(0.5);
	for (const row of geometry.rows) {
		expect.soft(Math.abs(row.right - geometry.resultCardContentRight),
			`${viewportWidth}px: result action row ends at its card edge`).toBeLessThanOrEqual(0.5);
		const items = row.items.slice().sort((left, right) => left.left - right.left);
		for (let index = 1; index < items.length; index++) {
			expect.soft(Math.abs(items[index].left - items[index - 1].right - geometry.expectedActionGap),
				`${viewportWidth}px: result actions use the shared inherited gap`).toBeLessThanOrEqual(0.5);
		}
		const heights = items.map(item => item.height);
		expect.soft(Math.max(...heights) - Math.min(...heights),
			`${viewportWidth}px: actions sharing a row have the same height`).toBeLessThanOrEqual(0.5);
	}
	const download = geometry.actions.find(action => action.role === 'download');
	const options = geometry.actions.find(action => action.role === 'options');
	if (download && options && requireNaturalFit) {
		expect.soft(Math.abs(download.top - options.top),
			`${viewportWidth}px: Download and Options remain associated on one row`).toBeLessThanOrEqual(0.5);
	}
	if (viewportWidth >= 1200 && requireNaturalFit) {
		expect.soft(geometry.rows, 'desktop actions that fit use one row').toHaveLength(1);
		const heights = geometry.actions.map(action => action.height);
		expect.soft(Math.max(...heights) - Math.min(...heights), 'desktop result action heights match')
			.toBeLessThanOrEqual(0.5);
	}
	if (viewportWidth <= 900 && requireNaturalFit) {
		expect.soft(new Set(geometry.actions.map(action => Math.round(action.width))).size,
			`${viewportWidth}px: result action widths follow their natural labels`).toBeGreaterThan(1);
	}
}

async function measureResultTarget(locator) {
	return locator.evaluate(target => {
		const targetRect = target.getBoundingClientRect();
		const targetStyle = getComputedStyle(target);
		const contentRight = targetRect.right - parseFloat(targetStyle.borderRightWidth)
			- parseFloat(targetStyle.paddingRight);
		const toolbarRect = target.querySelector('.query-result-toolbar').getBoundingClientRect();
		const actions = Array.from(target.querySelectorAll(
			'.query-results__fullscreen, .query-result-download-toggle, .query-result-options-toggle'))
			.filter(element => {
				const rect = element.getBoundingClientRect();
				return rect.width > 0 && rect.height > 0 && !element.closest('[hidden], [inert]');
			}).map(element => {
				const rect = element.getBoundingClientRect();
				return {
					role: element.matches('.query-results__fullscreen') ? 'fullscreen'
						: element.matches('.query-result-download-toggle') ? 'download' : 'options',
					left: rect.left, right: rect.right, top: rect.top, bottom: rect.bottom,
					toolbarTop: rect.top - toolbarRect.top, toolbarLeft: rect.left - toolbarRect.left,
					documentTop: rect.top + window.scrollY, width: rect.width, height: rect.height
				};
			}).sort((left, right) => left.left - right.left);
		const rows = [];
		for (const action of actions.slice().sort((left, right) => left.top - right.top || left.left - right.left)) {
			let row = rows.find(candidate => Math.abs(candidate.top - action.top) <= 0.75);
			if (!row) {
				row = { top: action.top, bottom: action.bottom, right: action.right, actions: [], items: [] };
				rows.push(row);
			}
			row.bottom = Math.max(row.bottom, action.bottom);
			row.right = Math.max(row.right, action.right);
			row.actions.push(action.role);
			row.items.push(action);
		}
		return {
			viewportWidth: document.documentElement.clientWidth,
			documentScrollWidth: document.documentElement.scrollWidth,
			expectedActionGap: parseFloat(getComputedStyle(document.body).getPropertyValue('--workbench-control-gap')),
			target: { left: targetRect.left, right: targetRect.right,
				contentRight, width: targetRect.width }, actions, rows
		};
	});
}

async function measureFullscreenCoverage(locator) {
	return locator.evaluate(target => {
		const rect = target.getBoundingClientRect();
		return {
			left: rect.left, top: rect.top, right: rect.right, bottom: rect.bottom,
			viewportWidth: document.documentElement.clientWidth,
			viewportHeight: document.documentElement.clientHeight,
			position: getComputedStyle(target).position
		};
	});
}

function assertFullscreenCoversViewport(geometry, context) {
	expect(geometry.position, `${context}: fullscreen target is fixed to the viewport`).toBe('fixed');
	expect(geometry.left, `${context}: fullscreen target covers the viewport's left edge`).toBeLessThanOrEqual(0.5);
	expect(geometry.top, `${context}: fullscreen target covers the viewport's top edge`).toBeLessThanOrEqual(0.5);
	expect(geometry.right, `${context}: fullscreen target covers the viewport's right edge`)
		.toBeGreaterThanOrEqual(geometry.viewportWidth - 0.5);
	expect(geometry.bottom, `${context}: fullscreen target covers the viewport's bottom edge`)
		.toBeGreaterThanOrEqual(geometry.viewportHeight - 0.5);
}

function assertResultTargetAlignment(geometry, viewportWidth, context) {
	expect.soft(geometry.actions, `${context} ${viewportWidth}px: result actions are visible`).toHaveLength(3);
	expect.soft(geometry.documentScrollWidth, `${context} ${viewportWidth}px: no document overflow`)
		.toBeLessThanOrEqual(geometry.viewportWidth);
	for (const row of geometry.rows) {
		expect.soft(Math.abs(row.right - geometry.target.contentRight),
			`${context} ${viewportWidth}px: each wrapped row ends at the result content edge`).toBeLessThanOrEqual(0.5);
		const items = row.items.slice().sort((left, right) => left.left - right.left);
		for (let index = 1; index < items.length; index++) {
			expect.soft(Math.abs(items[index].left - items[index - 1].right - geometry.expectedActionGap),
				`${context} ${viewportWidth}px: related actions use the shared inherited gap`)
				.toBeLessThanOrEqual(0.5);
		}
		const heights = items.map(item => item.height);
		expect.soft(Math.max(...heights) - Math.min(...heights),
			`${context} ${viewportWidth}px: actions sharing a row have the same height`)
			.toBeLessThanOrEqual(0.5);
	}
	const download = geometry.actions.find(action => action.role === 'download');
	const options = geometry.actions.find(action => action.role === 'options');
	if (download && options) {
		expect.soft(Math.abs(download.top - options.top),
			`${context} ${viewportWidth}px: Download and Options remain associated on one row`).toBeLessThanOrEqual(0.5);
	}
	if (viewportWidth >= 1200) {
		expect.soft(geometry.rows, `${context}: all desktop actions fit on one row`).toHaveLength(1);
	}
	if (viewportWidth <= 900) {
		expect.soft(new Set(geometry.actions.map(action => Math.round(action.width))).size,
			`${context} ${viewportWidth}px: result action widths follow their natural labels`).toBeGreaterThan(1);
	}
}

test.beforeAll(async ({ request }) => {
	const absent = await request.get(REPOSITORY_URL);
	expect([400, 404], `Refuse to reuse non-owned repository ${REPOSITORY}`).toContain(absent.status());
	const created = await request.put(REPOSITORY_URL, {
		headers: { 'Content-Type': 'text/turtle' },
		data: `@prefix c: <tag:rdf4j.org,2023:config/>.
[] a c:Repository; c:rep.id "${REPOSITORY}";
 c:rep.impl [c:rep.type "openrdf:SailRepository"; c:sail.impl [c:sail.type "openrdf:MemoryStore"]].`
	});
	expect([200, 201, 204]).toContain(created.status());
	repositoryCreated = true;
});

test.afterAll(async ({ request }) => {
    if (!repositoryCreated) return;
    if (savedQueryUrn) {
        const removed = await request.post(`${WORKBENCH}/repositories/${REPOSITORY}/saved-queries`, {
            form: { delete: savedQueryUrn }
        });
        expect([200, 204]).toContain(removed.status());
        savedQueryUrn = null;
    }
    const deleted = await request.delete(REPOSITORY_URL).catch(() => null);
    if (deleted) expect([200, 204, 400, 404]).toContain(deleted.status());
});

test.afterEach(async ({ request }) => {
    if (!savedQueryUrn) return;
    const removed = await request.post(`${WORKBENCH}/repositories/${REPOSITORY}/saved-queries`, {
        form: { delete: savedQueryUrn }
    });
    expect([200, 204]).toContain(removed.status());
    savedQueryUrn = null;
});

test('main desktop actions share the card content edge and one row', async ({ page }, testInfo) => {
	const pageErrors = [];
	const queryPosts = [];
	page.on('pageerror', error => pageErrors.push(error.message));
	page.on('console', message => {
		if (message.type() === 'error') pageErrors.push(`console: ${message.text()}`);
	});
	page.on('request', request => {
		if (request.method() === 'POST' && new URL(request.url()).pathname.endsWith('/query')
				&& new URLSearchParams(request.postData() || '').get('action') === 'exec') {
			queryPosts.push(request.url());
		}
	});
	await page.setViewportSize({ width: 1280, height: 1000 });
	await page.goto(QUERY_URL, { waitUntil: 'domcontentloaded' });
	await expect(page.locator('#workbench-page-surface')).toBeVisible();
	await expect(page.locator('#query-form')).toBeVisible();
	await expect(page.locator('#query-primary-pane .CodeMirror').first()).toBeVisible();
	await page.evaluate(() => window.RDF4JWorkbenchTheme.setPreference('dark'));
	await page.evaluate(async () => {
		await document.fonts.ready;
		await new Promise(resolve => requestAnimationFrame(() => requestAnimationFrame(resolve)));
	});
	const query = 'SELECT ?item WHERE { VALUES ?item { "alignment" } }';
	await page.locator('#query-primary-pane .CodeMirror').first()
		.evaluate((editor, value) => editor.CodeMirror.setValue(value), query);
	await page.locator('#exec').click();
	await expect(page.locator('#query-results')).toHaveAttribute('aria-busy', 'false');
	const result = page.locator('#query-results [data-query-stream-root]');
	await expect(result).toBeVisible();
	for (const selector of ['.query-results__fullscreen', '.query-result-download-toggle', '.query-result-options-toggle']) {
		await expect(page.locator(`#query-results ${selector}:visible`).first()).toBeVisible();
	}
	await page.evaluate(async () => new Promise(resolve => requestAnimationFrame(() => requestAnimationFrame(resolve))));

	const geometry = await measureMainAlignment(page);
	const artifact = testInfo.outputPath('main-desktop-action-alignment.json');
	fs.writeFileSync(artifact, JSON.stringify(geometry, null, 2));
	await testInfo.attach('main-desktop-action-alignment', { path: artifact, contentType: 'application/json' });
	await page.screenshot({ path: testInfo.outputPath('main-desktop-action-alignment.png'), fullPage: true });
	await testInfo.attach('main-desktop-screenshot', {
		path: testInfo.outputPath('main-desktop-action-alignment.png'), contentType: 'image/png'
	});
	expect(queryPosts, 'the native interaction should execute the query exactly once').toHaveLength(1);
	assertMainAlignment(geometry, 1280);
	const widths = [1280, 390, 320];
	for (const width of widths) {
		if (width !== 1280) {
			await page.setViewportSize({ width, height: 1000 });
			await page.evaluate(async () => new Promise(resolve => requestAnimationFrame(() => requestAnimationFrame(resolve))));
		}
		const responsive = width === 1280 ? geometry : await measureMainAlignment(page);
		assertMainAlignment(responsive, width);
		if (width !== 1280) {
			const file = testInfo.outputPath(`main-${width}-action-alignment.json`);
			fs.writeFileSync(file, JSON.stringify(responsive, null, 2));
			await testInfo.attach(`main-${width}-action-alignment`, { path: file, contentType: 'application/json' });
			const screenshot = testInfo.outputPath(`main-${width}-action-alignment.png`);
			await page.screenshot({ path: screenshot, fullPage: true, caret: 'hide' });
			await testInfo.attach(`main-${width}-action-alignment-screenshot`, { path: screenshot, contentType: 'image/png' });
		}
		const optionsToggle = page.locator('#query-results .query-result-options-toggle:visible').first();
		const downloadToggle = page.locator('#query-results .query-result-download-toggle:visible').first();
		const optionsPanel = page.locator(`#${await optionsToggle.getAttribute('aria-controls')}`);
		const positionsBefore = await measureMainAlignment(page);
		await optionsToggle.click();
		await expect(optionsPanel).toBeVisible();
		await page.evaluate(async () => new Promise(resolve => requestAnimationFrame(() => requestAnimationFrame(resolve))));
		const positionsAfter = await measureMainAlignment(page);
		for (const role of ['fullscreen', 'download', 'options']) {
			const before = positionsBefore.actions.find(action => action.role === role);
			const after = positionsAfter.actions.find(action => action.role === role);
			expect.soft(Math.abs(before.toolbarTop - after.toolbarTop),
				`${width}px: opening Options does not move the settled ${role} trigger`).toBeLessThanOrEqual(0.5);
			expect.soft(Math.abs(before.toolbarLeft - after.toolbarLeft),
				`${width}px: opening Options does not move the settled ${role} trigger horizontally`).toBeLessThanOrEqual(0.5);
		}
		await downloadToggle.click();
		await expect(optionsPanel).toBeHidden();
		await expect(downloadToggle).toHaveAttribute('aria-expanded', 'true');
		await downloadToggle.click();
		await expect(downloadToggle).toHaveAttribute('aria-expanded', 'false');
	}
	await page.setViewportSize({ width: 1280, height: 1000 });
	await page.evaluate(() => document.body.style.setProperty('--workbench-control-gap', '14px'));
	await page.evaluate(async () => new Promise(resolve => requestAnimationFrame(() => requestAnimationFrame(resolve))));
	const tokenGeometry = await measureMainAlignment(page);
	const tokenGaps = tokenGeometry.actions.slice(1).map((action, index) => action.left - tokenGeometry.actions[index].right);
	expect.soft(tokenGaps.length, 'desktop result actions expose within-row token spacing').toBe(2);
	for (const gap of tokenGaps) {
		expect.soft(Math.abs(gap - 14), 'result action spacing follows its inherited control-gap token')
			.toBeLessThanOrEqual(0.5);
	}
	await page.evaluate(() => document.body.style.removeProperty('--workbench-control-gap'));
	const fullScreen = page.locator('#query-results .query-results__fullscreen:visible').first();
	await fullScreen.click();
	await expect(page.locator('#query-results')).toHaveAttribute('data-fullscreen', 'true');
	await expect(fullScreen).toHaveAttribute('aria-pressed', 'true');
	assertFullscreenCoversViewport(await measureFullscreenCoverage(page.locator('#query-results')), 'main result');
	await page.keyboard.press('Escape');
	await expect(page.locator('#query-results')).not.toHaveAttribute('data-fullscreen', 'true');
	await expect(fullScreen).toHaveAttribute('aria-pressed', 'false');
	await expect.poll(() => page.evaluate(() => document.activeElement?.classList.contains('query-results__fullscreen')))
		.toBe(true);
	const fallbackFrameWasHidden = await page.evaluate(() => {
		const frame = document.getElementById('query-results-frame');
		const wasHidden = frame.hidden;
		frame.hidden = false;
		frame.focus();
		return wasHidden;
	});
	await expect.poll(() => page.evaluate(() =>
		document.activeElement === document.getElementById('query-results-frame')))
		.toBe(true);
	const focusedFallbackFrame = await page.evaluate(() =>
		document.activeElement === document.getElementById('query-results-frame'));
	let entered = false;
	let restoredParentControl = false;
	let bodyUnlocked = false;
	try {
		await page.evaluate(() => {
			const results = document.getElementById('query-results');
			const button = results.querySelector('.query-result-toolbar .query-results__fullscreen');
			window.workbench.query.toggleResultsFullscreen(results, button);
		});
		await expect(page.locator('#query-results')).toHaveAttribute('data-fullscreen', 'true');
		await expect.poll(() => page.evaluate(() => {
			const results = document.getElementById('query-results');
			const button = results.querySelector('.query-result-toolbar .query-results__fullscreen');
			return window.workbench.resultFullscreen.currentTarget() === results
				&& document.activeElement === button;
		})).toBe(true);
		entered = await page.evaluate(() => {
			const results = document.getElementById('query-results');
			const button = results.querySelector('.query-result-toolbar .query-results__fullscreen');
			return results.getAttribute('data-fullscreen') === 'true'
				&& window.workbench.resultFullscreen.currentTarget() === results
				&& document.activeElement === button;
		});
		await page.evaluate(() => {
			const results = document.getElementById('query-results');
			const button = results.querySelector('.query-result-toolbar .query-results__fullscreen');
			window.workbench.query.toggleResultsFullscreen(results, button);
		});
		await expect(page.locator('#query-results')).not.toHaveAttribute('data-fullscreen', 'true');
		await expect.poll(() => page.evaluate(() => {
			const results = document.getElementById('query-results');
			const button = results.querySelector('.query-result-toolbar .query-results__fullscreen');
			return document.activeElement === button
				&& !document.body.classList.contains('query-results-fullscreen-active');
		})).toBe(true);
		restoredParentControl = await page.evaluate(() => {
			const results = document.getElementById('query-results');
			return document.activeElement === results.querySelector('.query-result-toolbar .query-results__fullscreen');
		});
		bodyUnlocked = await page.evaluate(() =>
			!document.body.classList.contains('query-results-fullscreen-active'));
	} finally {
		await page.evaluate(wasHidden => {
			document.getElementById('query-results-frame').hidden = wasHidden;
		}, fallbackFrameWasHidden);
	}
	const iframeFocusRestoration = { focusedFallbackFrame, entered, restoredParentControl, bodyUnlocked };
	expect(iframeFocusRestoration.focusedFallbackFrame,
		'the focused legacy result iframe provides the parent document focus scenario').toBe(true);
	expect(iframeFocusRestoration.entered,
		`main fullscreen enters through the query adapter: ${JSON.stringify(iframeFocusRestoration)}`).toBe(true);
	expect(iframeFocusRestoration.restoredParentControl,
		'main fullscreen restores focus to its Full screen control after an iframe-owned entry').toBe(true);
	expect(iframeFocusRestoration.bodyUnlocked, 'iframe focus restoration exits fullscreen cleanly').toBe(true);
	await page.setViewportSize({ width: 1280, height: 1000 });
	const stress = await result.evaluate(root => {
		const longLabel = ' action with a long descriptive label';
		const title = root.querySelector('.query-result-toolbar__header h2');
		const fullscreenLabel = root.querySelector('.query-results__fullscreen-label');
		const downloadLabel = root.querySelector('.query-result-download-toggle .workbench-disclosure__toggle-label');
		const optionsLabel = root.querySelector('.query-result-options-toggle .workbench-disclosure__toggle-label');
		for (const label of [title, fullscreenLabel, downloadLabel, optionsLabel]) {
			if (label) label.textContent = label.textContent.trim() + longLabel.repeat(4);
		}
		const cell = root.querySelector('.query-result-table-wrap tbody td');
		if (cell) {
			cell.style.whiteSpace = 'nowrap';
			cell.style.minWidth = '1400px';
		}
		const scrollport = root.querySelector('.query-result-table-wrap');
		return { scrollportWidth: scrollport?.clientWidth, scrollWidth: scrollport?.scrollWidth };
	});
	expect(stress.scrollWidth, 'long result content creates an internal horizontal scrollport')
		.toBeGreaterThan(stress.scrollportWidth);
	const stressedGeometry = await measureMainAlignment(page);
	assertMainAlignment(stressedGeometry, 1280, { requireNaturalFit: false });
	const stressGeometryPath = testInfo.outputPath('main-long-labels-and-scrollbar.json');
	fs.writeFileSync(stressGeometryPath, JSON.stringify(stressedGeometry, null, 2));
	await testInfo.attach('main-long-labels-and-scrollbar-geometry', {
		path: stressGeometryPath, contentType: 'application/json'
	});
	const stressPath = testInfo.outputPath('main-long-labels-and-scrollbar.png');
	await page.screenshot({ path: stressPath, fullPage: true, caret: 'hide' });
	await testInfo.attach('main-long-labels-and-scrollbar', { path: stressPath, contentType: 'image/png' });
	expect(pageErrors, 'the rendered query flow should not produce browser errors').toEqual([]);
});

test('saved query fullscreen enters and exits on its own result target', async ({ page }, testInfo) => {
	const pageErrors = [];
	const queryPosts = [];
	page.on('pageerror', error => pageErrors.push(error.message));
	page.on('console', message => {
		if (message.type() === 'error') pageErrors.push(`console: ${message.text()}`);
	});
	page.on('request', request => {
		if (request.method() === 'POST' && new URL(request.url()).pathname.endsWith('/query')
				&& new URLSearchParams(request.postData() || '').get('action') === 'exec') {
			queryPosts.push(request.url());
		}
	});
	await page.setViewportSize({ width: 1280, height: 1000 });
	await page.goto(QUERY_URL, { waitUntil: 'domcontentloaded' });
	await expect(page.locator('#workbench-page-surface')).toBeVisible();
	await page.evaluate(() => window.RDF4JWorkbenchTheme.setPreference('dark'));
	await page.evaluate(async () => {
		await document.fonts.ready;
		await new Promise(resolve => requestAnimationFrame(() => requestAnimationFrame(resolve)));
	});
	const query = 'SELECT ?item WHERE { VALUES ?item { "saved fullscreen" } }';
	await page.locator('#query-primary-pane .CodeMirror').first()
		.evaluate((editor, value) => editor.CodeMirror.setValue(value), query);
	await page.locator('#save-query-toggle').click();
	await page.locator('#query-name').pressSequentially(SAVED_QUERY_NAME);
	await expect(page.locator('#save')).toBeEnabled();
	await page.locator('#save').click();
	await expect(page.locator('#save-feedback')).toContainText('Query saved.');
	await page.goto(`${WORKBENCH}/repositories/${REPOSITORY}/saved-queries`, { waitUntil: 'domcontentloaded' });
	await expect(page.locator('#workbench-page-surface')).toBeVisible();
	const row = page.locator('.saved-query-row').filter({ hasText: SAVED_QUERY_NAME }).first();
	await expect(row).toBeVisible();
	savedQueryUrn = await row.locator('.saved-query-delete').getAttribute('data-query-urn');
	expect(savedQueryUrn, 'only this test-owned saved query is removed').toBeTruthy();
	await row.locator('input[type=submit][value=Execute]').click();
	const results = row.locator('[id^=saved-query-results-]');
	const renderer = results.locator('[data-query-stream-root]');
	await expect(renderer).toBeVisible();
	await expect(results).toHaveAttribute('aria-busy', 'false');
	await expect(page.locator('#query-results')).toHaveCount(0);
	const fullscreen = renderer.locator('.query-results__fullscreen');
	await expect(fullscreen).toBeVisible();
	const before = testInfo.outputPath('saved-result-before-fullscreen.png');
	await page.screenshot({ path: before, fullPage: true, caret: 'hide' });
	await testInfo.attach('saved-result-before-fullscreen', { path: before, contentType: 'image/png' });
	await fullscreen.click();
	await expect.soft(results, 'fullscreen state belongs to the saved result mount').toHaveAttribute('data-fullscreen', 'true');
	await expect.soft(fullscreen).toHaveAttribute('aria-pressed', 'true');
	await expect.soft(page.locator('body')).toHaveClass(/query-results-fullscreen-active/);
	const fullscreenSurface = await results.evaluate(element => ({
		backgroundColor: getComputedStyle(element).backgroundColor,
		backgroundImage: getComputedStyle(element).backgroundImage
	}));
	expect.soft(fullscreenSurface.backgroundColor,
		'saved fullscreen result surface must cover the Workbench chrome with an opaque background')
		.not.toBe('rgba(0, 0, 0, 0)');
	const fullscreenScreenshot = testInfo.outputPath('saved-result-fullscreen.png');
	await page.screenshot({ path: fullscreenScreenshot, fullPage: true, caret: 'hide' });
	await testInfo.attach('saved-result-fullscreen', { path: fullscreenScreenshot, contentType: 'image/png' });
	assertFullscreenCoversViewport(await measureFullscreenCoverage(results), 'saved result');
	await page.keyboard.press('Escape');
	await expect.soft(results).not.toHaveAttribute('data-fullscreen', 'true');
	await expect.soft(fullscreen).toHaveAttribute('aria-pressed', 'false');
	await expect.soft(page.locator('body')).not.toHaveClass(/query-results-fullscreen-active/);
	await expect.poll(() => page.evaluate(() => document.activeElement?.classList.contains('query-results__fullscreen')))
		.toBe(true);
	const savedSourceToggle = row.locator('.saved-query-toggle');
	await expect(savedSourceToggle).toHaveAttribute('value', 'Show');
	await savedSourceToggle.click();
	await expect(savedSourceToggle).toHaveAttribute('value', 'Hide');
	await expect(results).toBeVisible();
	await savedSourceToggle.click();
	await expect(savedSourceToggle).toHaveAttribute('value', 'Show');
	await expect(results).toBeVisible();
	for (const width of [1280, 390, 320]) {
		await page.setViewportSize({ width, height: 1000 });
		await page.evaluate(async () => new Promise(resolve => requestAnimationFrame(() => requestAnimationFrame(resolve))));
		const geometry = await measureResultTarget(results);
		assertResultTargetAlignment(geometry, width, 'saved result');
		if (width !== 1280) {
			const json = testInfo.outputPath(`saved-${width}-action-alignment.json`);
			fs.writeFileSync(json, JSON.stringify(geometry, null, 2));
			await testInfo.attach(`saved-${width}-action-alignment`, { path: json, contentType: 'application/json' });
			const screenshot = testInfo.outputPath(`saved-${width}-action-alignment.png`);
			await page.screenshot({ path: screenshot, fullPage: true, caret: 'hide' });
			await testInfo.attach(`saved-${width}-action-alignment-screenshot`, { path: screenshot, contentType: 'image/png' });
		}
		const optionsToggle = renderer.locator('.query-result-options-toggle:visible').first();
		const downloadToggle = renderer.locator('.query-result-download-toggle:visible').first();
		const panel = page.locator(`#${await optionsToggle.getAttribute('aria-controls')}`);
		const before = await measureResultTarget(results);
		await optionsToggle.click();
		await expect(panel).toBeVisible();
		await page.evaluate(async () => new Promise(resolve => requestAnimationFrame(() => requestAnimationFrame(resolve))));
		const after = await measureResultTarget(results);
		for (const role of ['fullscreen', 'download', 'options']) {
			const prior = before.actions.find(action => action.role === role);
			const settled = after.actions.find(action => action.role === role);
			expect.soft(Math.abs(prior.toolbarTop - settled.toolbarTop),
				`saved ${width}px: opening Options keeps the ${role} trigger stable`).toBeLessThanOrEqual(0.5);
			expect.soft(Math.abs(prior.toolbarLeft - settled.toolbarLeft),
				`saved ${width}px: opening Options keeps the ${role} trigger aligned horizontally`)
				.toBeLessThanOrEqual(0.5);
		}
		await downloadToggle.click();
		await expect(panel).toBeHidden();
		await expect(downloadToggle).toHaveAttribute('aria-expanded', 'true');
		await downloadToggle.click();
		await expect(downloadToggle).toHaveAttribute('aria-expanded', 'false');
	}
	await page.evaluate(async () => new Promise(resolve => requestAnimationFrame(() => requestAnimationFrame(resolve))));
	const after = testInfo.outputPath('saved-result-after-fullscreen.png');
	await page.screenshot({ path: after, fullPage: true, caret: 'hide' });
	await testInfo.attach('saved-result-after-fullscreen', { path: after, contentType: 'image/png' });
	expect(queryPosts, 'saving and rendering should execute exactly one query').toHaveLength(1);
	expect(pageErrors, 'saved result fullscreen should not produce browser errors').toEqual([]);
});
